export const RELATORIO_030519_MAP = new Map<string, Relatorio030519Item>();

RELATORIO_030519_RAW_ITEMS.forEach(item => {
  RELATORIO_030519_MAP.set(String(item.codigo), item);
  RELATORIO_030519_MAP.set(item.codigoFormatado, item);
  RELATORIO_030519_MAP.set(String(item.codigo).padStart(7, '0'), item);
});

export function getRelatorio030519Item(codigo: string | number): Relatorio030519Item | null {
  if (codigo === undefined || codigo === null) return null;
  const rawStr = String(codigo).trim();
  if (!rawStr) return null;

  if (RELATORIO_030519_MAP.has(rawStr)) return RELATORIO_030519_MAP.get(rawStr)!;

  const digits = rawStr.replace(/\D/g, '');
  if (digits) {
    const num = parseInt(digits, 10);
    const numStr = String(num);
    if (RELATORIO_030519_MAP.has(numStr)) return RELATORIO_030519_MAP.get(numStr)!;

    const padded7 = numStr.padStart(7, '0');
    if (RELATORIO_030519_MAP.has(padded7)) return RELATORIO_030519_MAP.get(padded7)!;
  }

  return null;
}
